const body = $json.body || $json;
const query = (body.query || '').trim();
const topK  = Math.min(Math.max(parseInt(body.top_k) || 5, 1), 20);
const tagFilter = body.tag_filter || null;

if (!query) {
  throw new Error('Missing required field: query');
}

return {
  json: { query, top_k: topK, tag_filter: tagFilter }
};

// Items: [0] = validate output, [1] = embed output
// After chained nodes, $input.all() has the embedding result;
// we reach back to Validate Input for the original params.
const embedding = $json.data?.[0]?.embedding;
if (!embedding) throw new Error('Embedding API returned no vector');

const query     = $('Validate Input').first().json.query;
const topK      = $('Validate Input').first().json.top_k;
const tagFilter = $('Validate Input').first().json.tag_filter;

return [{ json: { query, top_k: topK, tag_filter: tagFilter, embedding } }];

const { embedding, top_k, tag_filter } = $json;

// Build optional tag filter
const filter = tag_filter ? {
  must: [{
    key: 'metadata.tags',
    match: { value: tag_filter }
  }]
} : undefined;

const body = {
  vector: embedding,
  limit: top_k,
  with_payload: true,
  score_threshold: 0.35,
  ...(filter ? { filter } : {})
};

const response = await fetch('http://qdrant:6333/collections/arxiv_papers/points/search', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'api-key': $vars.QDRANT_API_KEY || ''
  },
  body: JSON.stringify(body)
});

if (!response.ok) {
  const err = await response.text();
  throw new Error(`Qdrant search failed: ${response.status} ${err}`);
}

const data = await response.json();
const results = (data.result || []).map(point => ({
  score:         point.score,
  title:         point.payload?.metadata?.title         || point.payload?.title         || 'Untitled',
  url:           point.payload?.metadata?.url           || point.payload?.url           || '',
  tags:          point.payload?.metadata?.tags          || point.payload?.tags          || [],
  relevance:     point.payload?.metadata?.relevance     || point.payload?.relevance     || '',
  what_it_does:  point.payload?.metadata?.what_it_does  || point.payload?.what_it_does  || '',
  how_it_works:  point.payload?.metadata?.how_it_works  || point.payload?.how_it_works  || '',
  why_it_matters:point.payload?.metadata?.why_it_matters|| point.payload?.why_it_matters|| '',
  thumbnail_url: point.payload?.metadata?.thumbnail_url || point.payload?.thumbnail_url || '',
  summary:       point.payload?.document || ''
}));

return [{ json: { ...$json, results } }];

